CREATE TABLE "product_visual_indexes" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "product_id" INTEGER NOT NULL, "media_id" UUID NOT NULL, "merchant_id" INTEGER NOT NULL, "image_type" VARCHAR(40) NOT NULL, "provider" VARCHAR(40) NOT NULL DEFAULT 'mock', "embedding_version" VARCHAR(40) NOT NULL DEFAULT 'v1', "external_ref" VARCHAR(255), "status" VARCHAR(20) NOT NULL DEFAULT 'PENDING', "is_search_eligible" BOOLEAN NOT NULL DEFAULT true, "search_priority" INTEGER NOT NULL DEFAULT 100, "indexed_at" TIMESTAMPTZ, "created_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "product_visual_indexes_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "product_visual_indexes_product_id_media_id_key" ON "product_visual_indexes"("product_id", "media_id");
CREATE INDEX "product_visual_indexes_status_is_search_eligible_idx" ON "product_visual_indexes"("status", "is_search_eligible");
ALTER TABLE "product_visual_indexes" ADD CONSTRAINT "product_visual_indexes_product_id_fkey" FOREIGN KEY ("product_id") REFERENCES "products"("id") ON DELETE CASCADE;
ALTER TABLE "product_visual_indexes" ADD CONSTRAINT "product_visual_indexes_merchant_id_fkey" FOREIGN KEY ("merchant_id") REFERENCES "merchants"("id") ON DELETE CASCADE;
